import React, { useState, useRef, useEffect } from 'react';
import { gsap } from 'gsap';

const content = {
  es: {
    title: 'Aprende de los Expertos.',
    subtitle: 'Nuestros ingenieros imparten conocimiento a más de 10,000 estudiantes a través de la BDS Academy en Udemy.',
    topRated: 'MEJOR VALORADO',
    new: 'NUEVO',
    course1Title: 'Master en Arquitectura Cloud',
    course1Desc: 'Domina AWS, Terraform y Kubernetes desde cero hasta nivel enterprise.',
    course2Title: 'Ingeniería de Datos con Python',
    course2Desc: 'Construye pipelines robustos, modelos de machine learning y analítica avanzada.'
  },
  en: {
    title: 'Learn from the Experts.',
    subtitle: 'Our engineers impart knowledge to over 10,000 students through the BDS Academy on Udemy.',
    topRated: 'TOP RATED',
    new: 'NEW',
    course1Title: 'Cloud Architecture Masterclass',
    course1Desc: 'Master AWS, Terraform, and Kubernetes from zero to enterprise level.',
    course2Title: 'Data Engineering with Python',
    course2Desc: 'Build robust pipelines, machine learning models, and advanced analytics.'
  }
};

const AcademySection = ({ language = 'es' }) => {
  const t = content[language];
  const [hoveredIndex, setHoveredIndex] = useState(null);
  const containerRef = useRef(null);

  useEffect(() => {
    // Subtle entry animation
    gsap.fromTo(containerRef.current, 
      { opacity: 0, y: 50 },
      { opacity: 1, y: 0, duration: 1, ease: 'power3.out', scrollTrigger: { trigger: containerRef.current, start: 'top 80%' } }
    );
  }, [language]);

  const courses = [
    { badge: t.topRated, title: t.course1Title, desc: t.course1Desc, link: 'https://www.udemy.com' },
    { badge: t.new, title: t.course2Title, desc: t.course2Desc, link: 'https://www.udemy.com' }
  ];

  return (
    <section id="academy" ref={containerRef} className="py-40 md:py-48 bg-[#f5f5f7] relative overflow-hidden">
      
      {/* Background Noise / Texture implied */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_bottom,_var(--tw-gradient-stops))] from-slate-200/50 via-transparent to-transparent -z-10" />

      <div className="max-w-7xl mx-auto px-6 text-center z-10">
        <h2 className="text-4xl md:text-[4rem] font-light tracking-tighter text-[#1d1d1f] mb-6 leading-none">
          {t.title}
        </h2>
        <p className="text-lg md:text-xl text-slate-500 font-light leading-relaxed max-w-2xl mx-auto mb-24 tracking-tight">
          {t.subtitle}
        </p>

        {/* Horizontal Accordion Layout (B2B Aesthetic) */}
        <div className="flex flex-col md:flex-row gap-4 h-auto md:h-[400px] w-full">
          {courses.map((course, idx) => (
            <a 
              key={idx}
              href={course.link}
              target="_blank" 
              rel="noopener noreferrer"
              onMouseEnter={() => setHoveredIndex(idx)}
              onMouseLeave={() => setHoveredIndex(null)}
              className={`relative overflow-hidden flex flex-col justify-between p-12 cursor-pointer border border-black/5 rounded-[2rem] transition-all duration-700 ease-[cubic-bezier(0.32,0.72,0,1)] ${hoveredIndex === idx ? 'md:flex-[2] bg-white shadow-xl' : hoveredIndex !== null ? 'md:flex-[0.5] opacity-50 bg-slate-50' : 'md:flex-1 bg-white shadow-sm'}`}
            >
              <div className="flex justify-between items-start w-full">
                <span className={`text-[10px] font-medium bg-slate-100 text-slate-500 px-3 py-1 rounded-full uppercase tracking-widest transition-opacity duration-500 ${hoveredIndex !== null && hoveredIndex !== idx ? 'opacity-0' : 'opacity-100'}`}>
                  {course.badge}
                </span>
                <div className="w-10 h-10 rounded-full bg-[#1d1d1f] text-white flex items-center justify-center transform -rotate-45 hover:rotate-0 transition-transform duration-500">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                </div>
              </div>
              
              <div className={`text-left w-full transition-all duration-700 ${hoveredIndex !== null && hoveredIndex !== idx ? 'md:opacity-0 md:translate-y-4' : 'opacity-100 translate-y-0'}`}>
                <h3 className="text-2xl md:text-4xl font-light tracking-tight text-[#1d1d1f] mb-4 leading-tight">{course.title}</h3>
                <p className="text-slate-500 font-light text-base max-w-sm leading-relaxed">{course.desc}</p>
              </div>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
};

export default AcademySection;
